-- ─── Catálogo do SIPOM ────────────────────────────────────────────────
-- Cópia das tabelas de referência do SIPOM, com os ids originais: é o que o
-- envio das ocorrências informa (natureza, área da unidade, OPM, materiais,
-- composição). Nomes de tabela e coluna seguem o SIPOM. Só leitura para a
-- aplicação: o catálogo pertence ao destino.
CREATE SCHEMA IF NOT EXISTS sipom;
GRANT USAGE ON SCHEMA sipom TO tevunah_app;

CREATE TABLE sipom.natureza_fatos (id integer PRIMARY KEY, nome text NOT NULL, rotulo text NOT NULL);
CREATE TABLE sipom.comandos (id integer PRIMARY KEY, nome text NOT NULL, abreviado text NOT NULL, risp text, deletado_em timestamp);
CREATE TABLE sipom.batalhoes (id integer PRIMARY KEY, cp_id integer NOT NULL REFERENCES sipom.comandos(id), nome text NOT NULL, abreviado text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.companhias (id integer PRIMARY KEY, cp_id integer, bpm_id integer, nome text NOT NULL, abreviado text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.cidade (id integer PRIMARY KEY, codigo integer, nome text NOT NULL);
CREATE TABLE sipom.bairro (id integer PRIMARY KEY, cidade_id integer NOT NULL REFERENCES sipom.cidade(id), nome text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.companhia_atuacao (id integer PRIMARY KEY, companhia_id integer NOT NULL REFERENCES sipom.companhias(id), bairro_id integer REFERENCES sipom.bairro(id), cidade_id integer REFERENCES sipom.cidade(id));
CREATE TABLE sipom.procedimentos (id integer PRIMARY KEY, nome text NOT NULL);
CREATE TABLE sipom.material_tipos (id integer PRIMARY KEY, nome text NOT NULL);
CREATE TABLE sipom.arma_tipos (id integer PRIMARY KEY, nome text NOT NULL, requerido smallint NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.arma_calibres (id integer PRIMARY KEY, nome text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.arma_marcas (id integer PRIMARY KEY, nome text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.veiculo_tipos (id integer PRIMARY KEY, codigo_tipos_veiculos integer NOT NULL, nome text NOT NULL);
CREATE TABLE sipom.veiculo_cores (id integer PRIMARY KEY, codigo_cor integer NOT NULL, nome text NOT NULL);
CREATE TABLE sipom.orcrims (id integer PRIMARY KEY, nome text NOT NULL, abreviatura text NOT NULL, deletado_em timestamp);
CREATE TABLE sipom.postos_graduacoes (id integer PRIMARY KEY, nome text NOT NULL, ordem integer, abreviado text NOT NULL, tipo smallint NOT NULL);
CREATE TABLE sipom.policiamentos_tipos (id integer PRIMARY KEY, nome text NOT NULL);
CREATE TABLE sipom.policiamentos_funcoes (id integer PRIMARY KEY, nome text NOT NULL);
CREATE TABLE sipom.policiamentos_tipos_funcoes (id integer PRIMARY KEY, policiamento_tipo_id integer NOT NULL REFERENCES sipom.policiamentos_tipos(id), policiamento_funcao_id integer NOT NULL REFERENCES sipom.policiamentos_funcoes(id));
CREATE TABLE sipom.atributos_tipos (id integer PRIMARY KEY, nome text NOT NULL);
CREATE TABLE sipom.atributos_subtipos (id integer PRIMARY KEY, atributo_tipo_id integer NOT NULL REFERENCES sipom.atributos_tipos(id), nome text NOT NULL);
CREATE INDEX bairro_cidade_idx ON sipom.bairro (cidade_id);
CREATE INDEX companhia_atuacao_bairro_idx ON sipom.companhia_atuacao (bairro_id);
CREATE INDEX companhia_atuacao_cidade_idx ON sipom.companhia_atuacao (cidade_id);

